const GROWN: L = l('Cost later = cost today × (1 + rise)^years, where rise is the yearly price rise.', 'आगे की लागत = आज की लागत × (1 + बढ़ोतरी)^साल, जहाँ बढ़ोतरी सालाना भाव-वृद्धि है।');
const UNPAID: L = l('Balance after m months with no payments = amount × (1 + monthly rate)^m. Interest = balance − amount.', 'बिना भुगतान के m महीने बाद बकाया = रकम × (1 + मासिक दर)^m। ब्याज = बकाया − रकम।');
const EMI_TOTAL: L = l('EMI = P × r × (1 + r)^n ÷ ((1 + r)^n − 1), r = yearly rate ÷ 12, n = months. Total paid = EMI × n. Interest = total paid − P.', 'EMI = P × r × (1 + r)^n ÷ ((1 + r)^n − 1), r = सालाना दर ÷ 12, n = महीने। कुल भुगतान = EMI × n। ब्याज = कुल भुगतान − P।');
const TAXSAVE: L = l('Tax saved = deduction × slab rate × 1.04, where 1.04 adds the 4% cess on the tax.', 'बचा टैक्स = कटौती × स्लैब दर × 1.04, जहाँ 1.04 टैक्स पर 4% सेस जोड़ता है।');
const REGIMES: L = l('New regime: slabs on (pay − ₹75,000), nil up to ₹12 lakh taxable (Sec 87A). Old regime: slabs on (pay − ₹50,000 − deductions), nil up to ₹5 lakh. Both add 4% cess. FY 2025-26.', 'नई रिजीम: (वेतन − ₹75,000) पर स्लैब, ₹12 लाख टैक्स-योग्य तक शून्य (धारा 87A)। पुरानी: (वेतन − ₹50,000 − कटौती) पर स्लैब, ₹5 लाख तक शून्य। दोनों पर 4% सेस। FY 2025-26।');
const STEPUP: L = l('Each month: balance × (1 + i) + SIP, where i is the yearly rate ÷ 12. The SIP is raised by the step-up % once a year. Flat SIP = the same with no raise.', 'हर महीने: बकाया × (1 + i) + SIP, जहाँ i सालाना दर ÷ 12। SIP साल में एक बार स्टेप-अप % से बढ़ती है। फ्लैट SIP = बिना बढ़ोतरी वही हिसाब।');
const SCAM_F: L = l('Nothing is calculated in this reel. The amounts in the sample message are made up to show what scammers write.', 'इस रील में कोई हिसाब नहीं है। नमूना संदेश की रकमें सिर्फ़ यह दिखाने के लिए गढ़ी गई हैं कि ठग क्या लिखते हैं।');
const SCAM_TAIL = ' The helpline 1930 is the national cybercrime helpline.';
